      firstValueFrom(this.http.get<string[]>(`${base}/grades`, { context: new HttpContext().set(LIVE, true) })),
    ]);
    if (this.session.sheetId() === sheet) {
      this.roles.set(roles);
      this.show(settings);
      this.grades.set(grades);
    }
  }

